"""Offline, self-contained report for the current terrain integration iteration."""
from pathlib import Path
import sys,json,base64,hashlib,io,re,html,collections
from PIL import Image
ROOT=Path(__file__).resolve().parents[1];run=sys.argv[1];OUT=Path(sys.argv[2]);world=Path(sys.argv[3]);R=ROOT/'runs'/run;D=ROOT/'review/previews'/run
s=json.loads((R/'spec.json').read_text());qa=json.loads((R/'audit.json').read_text());wc=json.loads((R/'world_check.json').read_text());images={};records=[]
for group in ['overview','walk']+[f'B{i:02d}'for i in range(1,19)]:
 recs=json.loads((D/(group+'_report.json')).read_text());records+=recs
 for rec in recs:
  p=D/rec['image'];im=Image.open(p);assert im.info['source_nbt_sha256']==s['source_nbt_sha256'];assert rec['sha256']==hashlib.sha256(p.read_bytes()).hexdigest();buf=io.BytesIO();im.convert('RGB').save(buf,format='WEBP',quality=88,method=6);images[p.stem]='data:image/webp;base64,'+base64.b64encode(buf.getvalue()).decode()
for name in ['terrain_section','terrace_exploded']:
 images[name]='data:image/svg+xml;base64,'+base64.b64encode((D/(name+'.svg')).read_bytes()).decode()
for name,p in [('before',ROOT/'review/previews/J03/day_SE.png'),('reference',ROOT/'input/Songshanhu_reference.png')]:
 im=Image.open(p).convert('RGB');im.thumbnail((1600,1200));buf=io.BytesIO();im.save(buf,format='WEBP',quality=87);images[name]='data:image/webp;base64,'+base64.b64encode(buf.getvalue()).decode()
(D/'all_views.json').write_text(json.dumps(records,indent=2));used=set()
def img(k,id=''):
 used.add(k);return f'<img class="zoom" data-img="{k}" '+(f'id="{id}" 'if id else'')+f'src="{images[k]}" alt="{k}" loading="lazy">'
def card(k,title,caption):return '<figure>'+img(k)+f'<figcaption><b>{title}</b><p>{caption}</p></figcaption></figure>'
def dl(p,mime,label):return '<a class="download" download="'+p.name+'" href="data:'+mime+';base64,'+base64.b64encode(p.read_bytes()).decode()+'">'+label+' ↓</a>'
def buttons(id,items,attribute='view'):return '<div class="controls" id="'+id+'">'+''.join('<button data-'+attribute+'="'+k+'">'+t+'</button>'for k,t in items)+'</div>'
css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f4f1e8;color:#2e4437;font:16px/1.75 system-ui,-apple-system,"Microsoft YaHei",sans-serif}header{display:flex;justify-content:space-between;gap:20px;padding:20px max(24px,calc((100vw - 1240px)/2));border-bottom:1px solid #cbd2c0}header b{letter-spacing:.16em;font-size:13px}nav{display:flex;gap:20px;flex-wrap:wrap}a{color:inherit;text-underline-offset:4px}nav a{text-decoration:none;font-size:13px}main{max-width:1240px;margin:auto;padding:30px 24px}section{padding:42px 0;border-bottom:1px solid #cbd2c0}h1{font-family:serif;font-size:clamp(42px,6vw,78px);font-weight:500;line-height:1.22;margin:16px 0}h2{font-size:30px;font-weight:600;margin:10px 0 22px}h3{font-size:23px;margin:8px 0}.kicker{font-size:12px;letter-spacing:.15em;color:#6a7b65}.intro{display:grid;grid-template-columns:1fr 1fr;align-items:end;gap:50px;margin-bottom:28px}.lead{font-size:18px;color:#536b58}.small{font-size:13px;color:#657761}.tag{border:1px solid #b1bea6;border-radius:30px;font-size:12px;padding:4px 12px;display:inline-block;margin:4px 4px 4px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}figure{margin:0;background:#e7e7dc;border:1px solid #c9d0bd;border-radius:7px;overflow:hidden}figure img{display:block;width:100%;aspect-ratio:1.4;object-fit:contain;cursor:zoom-in}figcaption{padding:15px 20px}figcaption p{font-size:13px;color:#61715d;margin:5px 0}.controls{display:flex;gap:7px;flex-wrap:wrap;margin:16px 0}button,.download,select{border:1px solid #b5c0a9;border-radius:5px;background:#fbfaf4;color:#33503a;padding:9px 14px;font:inherit;font-size:13px;text-decoration:none;cursor:pointer}button:hover,button.active,.download:hover{background:#3e6147;color:#fff}button:focus-visible,a:focus-visible,select:focus-visible{outline:3px solid #c68c67;outline-offset:3px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin-top:26px}.stats div{border-left:2px solid #8eaa83;padding-left:16px}.stats strong{font-size:27px;display:block}.stats span{font-size:13px;color:#68785f}.note{border-left:3px solid #b48d6e;background:#e9eadc;padding:18px 22px;margin:22px 0;font-size:14px}details{background:#e9eddf;padding:16px 20px;margin-top:22px;border-radius:6px}summary{cursor:pointer;font-weight:600}table{border-collapse:collapse;width:100%;margin:20px 0}td,th{border-bottom:1px solid #ccd4c1;padding:12px 10px;text-align:left;font-size:14px}th{background:#e6ebdc}.map-wrap{background:#b7c79f;border-radius:7px;overflow:hidden}.map-wrap svg{display:block;width:100%;max-height:850px}.lot{cursor:pointer}.lot:hover rect,.lot.active rect{fill:#e0aa6c;stroke:#8b4c2c;stroke-width:1.2}.lot text{pointer-events:none}.building-layout{display:grid;grid-template-columns:1fr 2fr;gap:24px;margin-top:25px}.meta{background:#e4e9d9;padding:23px;border-radius:7px}.meta p{font-size:14px}.meta code{display:block;font-size:12px;background:#faf9f2;padding:12px;overflow-wrap:anywhere}.build-list{max-height:310px;overflow:auto;margin-top:16px}.building-name{display:block;width:100%;text-align:left;margin-bottom:6px}footer{font-size:12px;color:#7b8971;padding:35px 0}dialog{background:#f4f1e8;border:0;border-radius:7px;max-width:96vw;max-height:96vh;padding:10px}dialog img{display:block;max-width:90vw;max-height:82vh;object-fit:contain}dialog button{float:right;margin:7px}dialog::backdrop{background:#152719d9}@media(max-width:740px){header{padding:16px;align-items:start}nav{gap:9px}.intro,.grid,.building-layout{grid-template-columns:1fr}.intro{gap:12px}main{padding:20px 16px}.stats{grid-template-columns:1fr 1fr}section{padding:30px 0}.build-list{max-height:180px}}'''
p=['<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>木漏日町 · 山溪与十八栋</title><style>'+css+'</style></head><body><header><b>KOMOREBI / 09</b><nav><a href="#terrain">山与溪</a><a href="#walk">小路</a><a href="#map">18 栋</a><a href="#download">进入地图</a></nav></header><main>']
p.append('<section><div class="intro"><div><div class="kicker">HAF 0.4 / '+run+' / 2026.10.30</div><h1>房子，<br>沿着山溪<br>安顿下来。</h1><span class="tag">西北山体 · 相对高差 30 格</span><span class="tag">18 栋 · 3 处开放公共节点</span></div><div><p class="lead">参考你提供的松山湖：山坡与溪流先形成场地，建筑分组落在台地，小路沿着高差接通每一扇门。</p><p>云杉构成山坡背景，竹林藏在转弯处，樱花点在桥边与院落。圆石为主的小路，把山麓住家、商店和溪边公共空间连起来。</p><p class="small">本轮采用自建地形；并非 Minecraft 原生种子生成。建筑保留原有可进入内饰。</p></div></div><figure>'+img('day_SE','hero-img')+'<figcaption><b id="hero-caption">山溪街区 · 东南鸟瞰</b><p>最终 NBT 同源离线预览；不是 Minecraft 客户端截图。</p></figcaption></figure>'+buttons('hero-controls',[('day_SE','整区日景'),('night_SE','整区夜景'),('valley_overview','山谷关系'),('main_bend','走进小路'),('creek_bridge','桥上看山涧')])+'<div class="stats"><div><strong>30 格</strong><span>山顶相对街区基准地面</span></div><div><strong>18 栋</strong><span>首层分布于多个台地标高</span></div><div><strong>'+str(len(s['trees']))+' 组树</strong><span>云杉 + '+str(sum(t['kind']=='cherry'for t in s['trees']))+' 组樱花</span></div><div><strong>'+str(len(s['bamboo']))+' 根竹</strong><span>两片竹林 · 避开道路与入口</span></div></div></section>')
p.append('<section id="terrain"><div class="kicker">01 / Terrain before buildings</div><h2>从三排街屋，转为山麓与溪谷。</h2><div class="grid">'+card('before','上一版 · J03 平地街区','保留作为历史基线。与新场地范围不同，不是等尺度像素对照。')+card('day_SE','这一版 · '+run+' 山溪街区','建筑朝向、位置和首层高度一起调整；道路不再形成三排六列。')+card('reference','你提供的松山湖参考','采用高低台地、绕行小路、桥头停留和建筑分组的关系；不复刻画面中的全部建筑。')+card('terrain_section','山体与台地剖面','原始地面、建设后地面和北侧建筑使用同一坐标；可以看见实际填挖。')+'</div><p>山体位于西北。山涧从山脚下降，穿过两侧建筑组团，汇入东侧溪流。北侧与西侧住宅较高，商店和浴场逐步落到低处。仅对建筑台地和道路肩部作局部修整，没有把整片山地压成统一标高。</p><div class="note">原始地形单独保存为 Terrain_Input.nbt。'+str(s['earthworks']['unchanged_columns'])+' 根地形柱保持原高程；'+str(s['earthworks']['changed_columns'])+' 根柱发生填挖，明细写入布局数据。这里只统计地面高程变化，不把房屋体积计作填土。</div></section>')
p.append('<section id="walk"><div class="kicker">02 / Paths, groves and thresholds</div><h2>转弯、上坡，再遇见一片竹林。</h2><div class="grid">'+card('main_bend','商店之间的转折','圆石主材，苔石、安山岩和砂砾按小片变化；支路在入口处收窄。')+card('hill_lane','沿山脚上行','石阶接台地；云杉、低草和挡土收边沿着高差变化。')+card('bamboo_lane','竹林路段','两片竹林按组布置，竹高 4–8 格，保留通行与建筑入口。')+card('creek_bridge','山涧与跨溪小桥','桥面跨过水体，北侧道路接山坡，南侧接商店与公共停留处。')+card('cherry_bank','溪边与樱色点景','从路径看溪边樱花与街屋；樱叶使用自身粉色材质。')+card('bath_front','低处的浴场与支路','浴场加烟囱，周边留有入口、小路和植被间隙。')+'</div><details><summary>夜景与其他路径</summary><div class="grid">'+card('main_bend_night','商店支路夜景','入口与转弯处布灯，森林背景保留暗部。')+card('creek_bridge_night','溪桥夜景','同机位夜景；真实游戏光照仍待实机。')+card('forest_edge','高处林缘','连续山脊、路径和建筑台地之间的关系。')+card('south_lane','低处支路','面向不同方向的店铺，连接到同一条连续步行网络。')+'</div></details><p>铺装的变化按区域与小片组织，圆石占主要面积；路缘局部转为草径。水岸保持完整承托，树与竹子避开主要通路。公共节点包括山麓休憩亭、桥头告示候坐处、溪边洗手休息台，均属于开放构筑物。</p></section>')
map_svg=(D/'terrain_map.svg').read_text().replace('<svg xmlns=', '<svg id="site-map" xmlns=',1)
p.append('<section id="map"><div class="kicker">03 / Eighteen addresses</div><h2>地形变了，房间依然能走进去。</h2><p>点击地块或建筑编号，查看本轮重新生成的门面与室内图。传送位置放在入口外侧，按每栋实际高度计算。</p><div class="map-wrap">'+map_svg+'</div><div class="building-layout"><aside class="meta"><div class="kicker" id="building-id"></div><h3 id="building-title"></h3><p id="building-info"></p><code id="tp-command"></code><label for="building-filter" class="small">楼型筛选</label><select id="building-filter"><option value="all">全部 18 栋</option><option value="machiya">大町屋 · 4 栋</option><option value="compact">紧凑两层 · 6 栋</option><option value="single">单层专门用途 · 8 栋</option></select><div class="build-list" id="building-list">'+''.join(f'<button class="building-name" data-building="{b["id"]}" data-family="{b["family"]}">{b["id"]}　{b["name"]}</button>'for b in s['buildings'])+'</div></aside><div>'+buttons('building-views',[('front','临街门面'),('inside','首层室内')],'mode')+'<figure>'+img('B01_front','building-img')+'<figcaption><b id="building-caption"></b><p>本栋附近的最终 NBT 几何裁取；保留墙、屋顶与天花，周边完整关系看街景。</p></figcaption></figure><a id="download-view" class="small" download="B01_front.webp" href="'+images['B01_front']+'">下载当前视图 ↓</a></div></div><details><summary>重点建筑：楼上起居与平面</summary><div class="grid">'+card('B01_upper','居酒屋上层','原有床组、起居与收纳随整栋平移、旋转到新的台地。')+card('B06_upper','山麓住家上层','实际床与床头、软席、衣柜和植物。')+card('B15_detail','山边文库','用途陈列和阅读空间，保留完整天花。')+card('B16_detail','低处浴场','原有室内浴池与干区；水的真实运行仍需进入游戏查看。')+''.join(card(b+'_plan',b+' 首层切层','仅在本栋实际标高切去上部，避免把不同高度的房子切错层。')for b in['B01','B06','B15','B16'])+'</div></details></section>')
p.append('<section><div class="kicker">04 / Shared spatial data</div><h2>先能读清地形，再谈自主排布。</h2><div class="grid">'+card('top','实际屋顶俯视','山体、溪流、公共节点与 18 栋布局同源。')+card('terrace_exploded','台地与楼层分层示意','展示不同标高的空间组织；地块示意，未将矩形视作精确木楼板。')+'</div><p>这次已把原始地形、采用的建筑落位、道路标高、水面保护范围和填挖明细分开保存。同一组种子重跑结果字节一致；另一组布局和植被种子使 18 栋在候选范围内换位，也通过入口与室内检查。以后换成你给出的地形 NBT，可先研究表面高程、陡坡、水系、已有建筑与可建设区域，再决定台地、建筑群和路径。</p><table><tr><th>当前已经完成</th><th>下一阶段需要验证</th></tr><tr><td>本案例先生成原始地形，再落位 18 栋并连接入口</td><td>读取任意用户 NBT，辨认地下洞穴、树冠、悬空结构与地表</td></tr><tr><td>输出每一栋的标高、朝向、边界与入口；保存道路与填挖数据</td><td>在未知地形上自动筛选地块、分配建筑用途并比较多个布局</td></tr><tr><td>受约束的位置扰动、植物分组和路面材料变化</td><td>将布局质量与可通行性、少填挖、景观视线一起评价</td></tr></table><div class="note">这是向“给地形 NBT → 自主设计建筑群”推进的一次有界试验。当前地形仍由本工程生成，不能把导出 Terrain_Input.nbt 说成已经具备任意 NBT 自动规划能力。</div><details><summary>四向立面与其他日夜角度</summary><div class="grid">'+''.join(card('elevation_'+k,t+'向立面','相同尺度；山体、树林与前排建筑存在真实遮挡。')for k,t in [('south','南'),('east','东'),('north','北'),('west','西')])+''.join(card(k,t,'最终结构同源；与本轮其他角度使用相同场地。')for k,t in [('day_SW','西南日景'),('day_NW','西北日景'),('day_NE','东北日景'),('night_SW','西南夜景'),('night_NW','西北夜景'),('night_NE','东北夜景')])+'</div></details></section>')
p.append('<section id="download"><div class="kicker">05 / Walk through the result</div><h2>进入这座山溪小镇。</h2><p>'+dl(world,'application/zip','Java 1.21.1 地图')+' '+dl(R/'Komorebi09.nbt','application/octet-stream','完整结构 NBT')+'</p><p>'+dl(R/'Terrain_Input.nbt','application/octet-stream','建设前地形 NBT')+' '+dl(R/'spatial_contract.json','application/json','建筑布局与填挖数据')+'</p><ol><li>解压地图包，把 <b>Komorebi09_1.21.1</b> 放进 Minecraft Java 1.21.1 的 <code>saves</code>。</li><li>出生点 <code>'+str(wc['spawn'])+'</code>。建议从低处商店街出发，经桥头到竹林，再往山麓住家与休憩亭走。</li><li>使用 <code>/time set night</code> 查看夜景；默认暂停昼夜、天气与植物随机更新。</li></ol><table><tr><th>检查</th><th>范围</th></tr><tr><td>18 栋入口 / 285 个使用点 / 10 条室内楼梯</td><td>最终结构回读通过；室外连接图允许一格高差和跳跃，尚未等同于全程无跳跃步行。</td></tr><tr><td>水岸、绿植、门框、画与储物</td><td>检查承托、配对、碰撞近似与边界围合；动态流水没有实机验证。</td></tr><tr><td>世界存档</td><td>'+f'{wc["checked_cells"]:,}'+' 格回读，'+str(wc['mismatches'])+' 差异；335 个方块实体、12 幅画载荷核对。</td></tr><tr><td>预览</td><td>'+str(len(records))+' 张本轮 PNG 均记录最终 NBT 哈希；网页使用压缩图显示。</td></tr></table><div class="note">结构 NBT 为稀疏结构，粘贴前须清空完整范围，直接使用地图包更方便。地图使用原版方块，并设置 taiga 群系标签；山体、云杉林、竹林与樱花为本次设计，不是原生群系生成。地图片区以外的继续生成与接缝仍待实机确认。</div><details><summary>版本与表现边界</summary><p>J03 为上一版平地街区。T01–T04 建立地形和布局适配；T05 加竹林与樱花；T06 延展北侧山脊、修正休憩亭柱与路径关系；'+run+' 保护水岸草径承托。工程保留原有 J03 与本轮关键记录。</p><p>仍使用三类有界建筑空间，不宣称 18 个全新独立户型。座椅与部分用品是原版方块造型，容器内部为空。原版材质颜色不等于彩色光传播。</p><p>全部视图由最终 NBT 离线绘制；纹理采样、旗帜、告示牌、床、水和光照有简化。没有客户端运行证据，审美、流体、碰撞与实际游走仍需实机验收。</p><p class="small">最终 NBT SHA-256：'+s['source_nbt_sha256']+'</p></details></section><footer>木漏日町 · 山溪版 / '+run+' / HAF 0.4<br>原始地形、采用结果与变化明细分开保留。源工程另附。</footer></main><dialog id="viewer"><img id="viewer-img" alt="放大预览"><button id="viewer-close">关闭</button></dialog>')
js='''const images=IMAGES;const buildings=BUILDINGS;const offset=OFFSET;let current='B01',mode='front';const $=id=>document.getElementById(id);function show(id,key){$(id).src=images[key];$(id).dataset.img=key;}function renderBuilding(){const b=buildings.find(x=>x.id===current),key=current+'_'+mode;show('building-img',key);$('building-caption').textContent=current+' · '+b.name+' · '+(mode==='front'?'门面':'首层室内');$('download-view').href=images[key];$('download-view').download=key+'.webp';document.querySelectorAll('#building-views button').forEach(e=>e.classList.toggle('active',e.dataset.mode===mode));}function choose(id){current=id;const b=buildings.find(x=>x.id===id);$('building-id').textContent=id;$('building-title').textContent=b.name;$('building-info').textContent=b.floors+' 层 · 首层地面 y='+b.floor_y+' · 朝向旋转 '+b.rotation+'°';let [x,y,z]=b.front_outside;$('tp-command').textContent='/tp @s '+(x+offset[0]+.5)+' '+(y+offset[1])+' '+(z+offset[2]+.5)+' '+((b.rotation+180)%360)+' 0';document.querySelectorAll('[data-building]').forEach(e=>e.classList.toggle('active',e.dataset.building===id));renderBuilding();}document.addEventListener('click',e=>{const b=e.target.closest('[data-building]');if(b){choose(b.dataset.building);return;}const im=e.target.closest('img.zoom');if(im){$('viewer-img').src=images[im.dataset.img];$('viewer').showModal();}});$('site-map').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){const b=e.target.closest('[data-building]');if(b){e.preventDefault();choose(b.dataset.building);}}});$('building-views').addEventListener('click',e=>{const b=e.target.closest('[data-mode]');if(b){mode=b.dataset.mode;renderBuilding();}});$('building-filter').addEventListener('change',e=>{document.querySelectorAll('#building-list button').forEach(b=>b.hidden=e.target.value!=='all'&&b.dataset.family!==e.target.value);});$('hero-controls').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(!b)return;show('hero-img',b.dataset.view);$('hero-caption').textContent=b.textContent;document.querySelectorAll('#hero-controls button').forEach(x=>x.classList.toggle('active',x===b));});$('viewer-close').addEventListener('click',()=>$('viewer').close());choose('B01');'''
js=js.replace('IMAGES','Object.assign(Object.fromEntries(Array.from(document.querySelectorAll("img[data-img]")).map(e=>[e.dataset.img,e.src])), '+json.dumps({k:v for k,v in images.items()if k not in used})+')').replace('BUILDINGS',json.dumps(s['buildings'],ensure_ascii=False)).replace('OFFSET',json.dumps(wc['world_offset']));p.append('<script>'+js+'</script></body></html>');OUT.write_text(''.join(p));print(json.dumps({'html_bytes':OUT.stat().st_size,'views':len(records)}))
